import{_ as r,C as i,o as l,c as s,j as e,a as c,E as o,a2 as d}from"./chunks/framework.BUrnCmah.js";const z=JSON.parse(`{"title":"Analisi del Marchio - Bticino (Legrand)","description":"Guida pratica all'integrazione di Bticino MyHome e Living Now con Netatmo in Home Assistant, tra ponte locale HomeKit e ottimizzazione dei costi.","frontmatter":{"title":"Analisi del Marchio - Bticino (Legrand)","description":"Guida pratica all'integrazione di Bticino MyHome e Living Now con Netatmo in Home Assistant, tra ponte locale HomeKit e ottimizzazione dei costi."},"headers":[],"relativePath":"blogs/overview/brand/bticino.md","filePath":"blogs/overview/brand/bticino.md"}`),m={name:"blogs/overview/brand/bticino.md"};function g(p,t,u,h,b,f){const a=i("BrandSummaryBar"),n=i("URL");return l(),s("div",null,[t[0]||(t[0]=e("h1",{id:"🏛️-analisi-del-marchio-bticino-legrand",tabindex:"-1"},[c("🏛️ Analisi del Marchio: Bticino (Legrand) "),e("a",{class:"header-anchor",href:"#🏛️-analisi-del-marchio-bticino-legrand","aria-label":'Permalink to "🏛️ Analisi del Marchio: Bticino (Legrand)"'},"​")],-1)),o(a,{"price-label":"Molto Alto (Premium)","price-tier":"high",rating:1,"rating-note":"Ecosistema chiuso: richiede ponte HomeKit o micromoduli alternativi"}),t[1]||(t[1]=d('<p>Bticino punta tutto sull&#39;<strong>integrazione architettonica</strong>. All&#39;interno di un Sistema Ibrido non viene scelta per risparmiare, ma per l&#39;estetica delle serie civili (come <strong>Living Now</strong>) e per la qualità percepita dei comandi fisici a muro.</p><h2 id="🔌-le-due-anime-di-bticino" tabindex="-1">🔌 Le Due Anime di Bticino <a class="header-anchor" href="#🔌-le-due-anime-di-bticino" aria-label="Permalink to &quot;🔌 Le Due Anime di Bticino&quot;">​</a></h2><h3 id="_1-myhome-cablato-scs" tabindex="-1">1. MyHome (Cablato SCS) <a class="header-anchor" href="#_1-myhome-cablato-scs" aria-label="Permalink to &quot;1. MyHome (Cablato SCS)&quot;">​</a></h3><p>Il sistema domotico bus professionale installato in fase di ristrutturazione o impianto dedicato.</p><ul><li><strong>Integrazione HA:</strong> richiede il gateway <strong>MyHomeServer1</strong> e comunica tramite protocollo <em>OpenWebNet</em>.</li><li><strong>Giudizio:</strong> molto stabile nel tempo, ma con costi elevati e scarsa flessibilità rispetto a soluzioni aperte.</li></ul><h3 id="_2-living-now-con-netatmo-wireless-ibrido" tabindex="-1">2. Living Now con Netatmo (Wireless / Ibrido) <a class="header-anchor" href="#_2-living-now-con-netatmo-wireless-ibrido" aria-label="Permalink to &quot;2. Living Now con Netatmo (Wireless / Ibrido)&quot;">​</a></h3><p>La linea più diffusa per adeguare impianti esistenti, basata su una variante proprietaria di <strong>Zigbee</strong> (Netatmo).</p><ul><li><strong>Vantaggi:</strong> design curato, installazione nelle comuni scatole 503, cover intercambiabili.</li><li><strong>Svantaggi:</strong> richiede il proprio Gateway Wi-Fi e la configurazione iniziale tramite app <em>Home + Control</em>.</li></ul><h2 id="🛠️-strategia-di-integrazione-il-ponte-locale" tabindex="-1">🛠️ Strategia di Integrazione: Il &quot;Ponte Locale&quot; <a class="header-anchor" href="#🛠️-strategia-di-integrazione-il-ponte-locale" aria-label="Permalink to &quot;🛠️ Strategia di Integrazione: Il &quot;Ponte Locale&quot;&quot;">​</a></h2><p>Per evitare di far passare ogni comando dal cloud Legrand/Netatmo, l&#39;approccio più efficace in Home Assistant è utilizzare <strong>HomeKit</strong> come ponte in rete locale.</p><h3 id="metodo-consigliato-homekit-device-controller" tabindex="-1">Metodo Consigliato: HomeKit Device (Controller) <a class="header-anchor" href="#metodo-consigliato-homekit-device-controller" aria-label="Permalink to &quot;Metodo Consigliato: HomeKit Device (Controller)&quot;">​</a></h3><ol><li><strong>Configurazione iniziale:</strong> associa gateway e frutti nell&#39;app ufficiale <em>Home + Control</em> e abilita Apple HomeKit.</li><li><strong>Integrazione in HA:</strong> aggiungi il gateway tramite l&#39;integrazione <strong>HomeKit Device</strong> in Home Assistant.</li><li><strong>Risultato:</strong> Home Assistant comunica direttamente in LAN con il gateway Bticino, con risposta istantanea e senza dipendere dal cloud per i comandi giornalieri.</li></ol><div class="tip custom-block"><p class="custom-block-title">Vantaggio Ibrido</p><p>Con Home Assistant come regia centrale puoi usare un interruttore Living Now a muro per comandare anche una lampadina economica Zigbee (ad esempio Lidl o IKEA), unendo estetica di fascia alta e costi contenuti sui punti luce.</p></div><h2 id="📐-anatomia-di-un-punto-luce-living-now" tabindex="-1">📐 Anatomia di un Punto Luce (Living Now) <a class="header-anchor" href="#📐-anatomia-di-un-punto-luce-living-now" aria-label="Permalink to &quot;📐 Anatomia di un Punto Luce (Living Now)&quot;">​</a></h2><p>Per comporre un punto luce completo della serie Living Now servono 4 componenti:</p><ol><li><strong>Supporto (es. K4703):</strong> il telaio che si fissa alla scatola 503.</li><li><strong>Frutto (Dispositivo):</strong> l&#39;interruttore, deviatore o presa vera e propria.</li><li><strong>Cover:</strong> il tasto frontale (Bianco, Sabbia o Nero).</li><li><strong>Placca:</strong> la cornice esterna di finitura.</li></ol><h3 id="💶-stima-prezzi-dei-singoli-componenti" tabindex="-1">💶 Stima Prezzi dei Singoli Componenti <a class="header-anchor" href="#💶-stima-prezzi-dei-singoli-componenti" aria-label="Permalink to &quot;💶 Stima Prezzi dei Singoli Componenti&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Componente</th><th style="text-align:left;">Codice</th><th style="text-align:left;">Descrizione</th><th style="text-align:left;">Prezzo Medio Indicativo</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Supporto</strong></td><td style="text-align:left;">K4703</td><td style="text-align:left;">Supporto 3 moduli con viti</td><td style="text-align:left;">€ 2,50 - 3,00</td></tr><tr><td style="text-align:left;"><strong>Placca Bianca</strong></td><td style="text-align:left;">KA4803KW</td><td style="text-align:left;">Placca Living Now 3 moduli</td><td style="text-align:left;">€ 7,00</td></tr><tr><td style="text-align:left;"><strong>Interruttore std</strong></td><td style="text-align:left;">K4001</td><td style="text-align:left;">Unipolare 10AX</td><td style="text-align:left;">€ 4,50</td></tr><tr><td style="text-align:left;"><strong>Presa Bipasso</strong></td><td style="text-align:left;">K4141</td><td style="text-align:left;">Presa 10/16A (Standard ITA)</td><td style="text-align:left;">€ 6,00</td></tr><tr><td style="text-align:left;"><strong>Cover Tasto</strong></td><td style="text-align:left;">KW01</td><td style="text-align:left;">Cover per interruttore 1 mod.</td><td style="text-align:left;">€ 1,50 - 2,00</td></tr><tr><td style="text-align:left;"><strong>Comando Smart</strong></td><td style="text-align:left;">K4500C</td><td style="text-align:left;">Interruttore connesso Zigbee</td><td style="text-align:left;">€ 45,00 - 50,00</td></tr></tbody></table><h2 id="🛒-esempi-di-composizioni-complete" tabindex="-1">🛒 Esempi di Composizioni Complete <a class="header-anchor" href="#🛒-esempi-di-composizioni-complete" aria-label="Permalink to &quot;🛒 Esempi di Composizioni Complete&quot;">​</a></h2><p>Valori medi indicativi per una composizione completa (Serie Living Now Bianca):</p><h3 id="_1-punto-luce-3-tasti-standard-non-smart" tabindex="-1">1. Punto Luce 3 Tasti Standard (Non Smart) <a class="header-anchor" href="#_1-punto-luce-3-tasti-standard-non-smart" aria-label="Permalink to &quot;1. Punto Luce 3 Tasti Standard (Non Smart)&quot;">​</a></h3><p><em>Indicato dove non serve automazione ma si vuole coerenza estetica.</em></p><ul><li>1 Supporto + 1 Placca Bianca + 3 Deviatori + 3 Cover.</li><li><strong>Totale indicativo:</strong> ~€ 32,00</li></ul><h3 id="_2-combo-2-tasti-1-presa-bipasso" tabindex="-1">2. Combo 2 Tasti + 1 Presa Bipasso <a class="header-anchor" href="#_2-combo-2-tasti-1-presa-bipasso" aria-label="Permalink to &quot;2. Combo 2 Tasti + 1 Presa Bipasso&quot;">​</a></h3><p><em>La configurazione classica da comodino.</em></p><ul><li>1 Supporto + 1 Placca Bianca + 2 Deviatori + 2 Cover + 1 Presa + 1 Cover Presa.</li><li><strong>Totale indicativo:</strong> ~€ 32,00</li></ul><h3 id="_3-presa-schuko-1-tasto" tabindex="-1">3. Presa Schuko + 1 Tasto <a class="header-anchor" href="#_3-presa-schuko-1-tasto" aria-label="Permalink to &quot;3. Presa Schuko + 1 Tasto&quot;">​</a></h3><p><em>Comune in cucina o vicino a elettrodomestici.</em></p><ul><li>1 Supporto + 1 Placca Bianca + 1 Presa Schuko (2 mod.) + 1 Cover Schuko + 1 Deviatore con Cover.</li><li><strong>Totale indicativo:</strong> ~€ 29,00</li></ul><h2 id="💡-nota-strategica-per-il-risparmio" tabindex="-1">💡 Nota Strategica per il Risparmio <a class="header-anchor" href="#💡-nota-strategica-per-il-risparmio" aria-label="Permalink to &quot;💡 Nota Strategica per il Risparmio&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Come risparmiare mantenendo l&#39;estetica Living Now</p><p>Rendere nativamente &quot;smart&quot; ogni singolo tasto Bticino costa intorno a <strong>€50 a punto luce</strong>.</p><p><strong>Approccio consigliato:</strong> installa frutti tradizionali (o pulsanti) Bticino e abbina nella scatola 503 un <strong>micromodulo Wi-Fi (Shelly)</strong> o <strong>Zigbee (Sonoff / Aqara)</strong>. Mantieni al 100% l&#39;estetica Living Now pagando la parte smart circa <strong>€15-20</strong> per punto luce.</p></div><h2 id="🎬-video-approfondimento" tabindex="-1">🎬 Video Approfondimento <a class="header-anchor" href="#🎬-video-approfondimento" aria-label="Permalink to &quot;🎬 Video Approfondimento&quot;">​</a></h2>',32)),o(n,{id:"c6XXwhSu0uM?si=PimscilPHGut-ZNz"})])}const x=r(m,[["render",g]]);export{z as __pageData,x as default};
